import { createMemo, createSignal, onCleanup, onMount, useContext, type JSX, type ParentComponent } from "solid-js";

import { InputEngineEventName, type InputEngineEvent } from "#core/ui/input/input-support.js";
import { TriggerActivationContext, TriggerType } from "#core/ui-next/components/trigger.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { AudioGroupContext } from "#core/ui-next/services/audio.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { isFocusable } from "#core/ui-next/services/focus.js";
import {
	HotkeyIconContext,
	HotkeyIconContextProvider,
	registerHotkey,
	registerNavTray,
} from "#core/ui-next/services/hotkey.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { useVfx } from "#core/ui-next/services/ui-vfx-support.js";
import { createPropsRefSignal } from "#core/ui-next/utilities/solid-utilities.js";

// Directive imports get destroyed by tree-shaking and auto-formatting - prevent that
export const PROTECTED_IMPORTS = [isFocusable, registerHotkey, registerNavTray];

const FEEDBACK_LOW = 20;
const FEEDBACK_HIGH = 20;
const FEEDBACK_DURATION = 100;

// Blank audio override that will cause the activatable to not make any sound
export const EMPTY_ACTIVATABLE_AUDIO: ActivatableAudio = {
	group: "",
	onActivate: "",
	onPress: "",
	onError: "",
	onFocus: "",
};

export interface ActivatableAudio {
	/** Audio group override */
	group?: string;
	/** Audio override for when the activatable finishes activating */
	onActivate?: string;
	/** Audio override for when the activatable starts activating */
	onPress?: string;
	/** Audio override for when the activatable is unable to activate */
	onError?: string;
	/** Audio override for when the activatable gains controller focus */
	onFocus?: string;
}

export interface ActivatableProps extends JSX.HTMLAttributes<HTMLDivElement> {
	/**
	 * The name to use as the component when resolving audio events.
	 * Otherwise, will use props.name, or "Activatable" if that is not set.
	 */
	audioComponentAlias?: string;
	/**
	 * The name to use as the component when resolving VFX events.
	 * Otherwise, will use props.name, or "Activatable" if that is not set.
	 */
	vfxComponentAlias?: string;

	/** Audio overrides for this control - See {@link ActivatableAudio} for a full list. */
	audio?: ActivatableAudio;
	/** Is this control disabled both visually and for input? Default: false */
	disabled?: boolean;
	/** Is controller focus disabled for this control? Default: false */
	disableFocus?: boolean;
	/** Should we suppress the pointer/disabled cursor? Used when activatables are present for gamepad purposes only. Default: false */
	suppressPointerChanges?: boolean;
	/** Is controller focus disabled for this control? Default: false */
	isFeedbackEnabled?: boolean;
	/** Disable trigger activation for this control. Default: false */
	disableTrigger?: boolean;
	/** The name of an input action which activates this component. This is only active when the activatable is focused. Default: accept */
	actionKey?: string;
	/** The name of a hotkey action which activates this component. This is active anywhere in the parent hotkey context. Default: undefined */
	hotkeyAction?: string;
	/** The name of the activatable; set as the data-name property - useful for debugging or searching the DOM tree. Default: Activatable */
	name?: string;
	/** The text which appears on the navTray with the given hotkeyAction. This will automatically hide this button. Default: undefined */
	navTrayText?: string;
	/** Event which triggers when the control is activated either through hotkey, mouse click, touch, or other user interaction */
	onActivate?: () => void;
	/** Event which triggers when this control loses controller focus */
	onBlur?: () => void;
	/** Event which triggers when this control gains controller focus */
	onFocus?: () => void;
	/** Auto focus this element? */
	autoFocus?: boolean;
	/** Engine input passthrough */
	"on:engine-input"?: (e: InputEngineEvent) => void;
}

const ActivatableComponent: ParentComponent<ActivatableProps> = (props) => {
	const audioComponentName = createMemo(() => {
		return props.audioComponentAlias ?? props.name ?? "Activatable";
	});
	const vfxComponentName = createMemo(() => {
		return props.vfxComponentAlias ?? props.name ?? "Activatable";
	});

	const audioTrigger = useAudio();
	const vfxTrigger = useVfx();

	// Trigger audio from context, this is to prevent duplicate audio from playing.
	function triggerUiSFX(eventName: string, attributeName: string) {
		if (!root()?.hasAttribute(attributeName)) {
			audioTrigger(audioComponentName(), eventName);
		} else {
			audioContext().playSound(attributeName, root());
		}
	}

	function triggerUiVFX(eventName: string) {
		const vfxPathAttributeData = root()?.getAttribute("data-vfx-path");
		const rects = root()?.getClientRects();
		if (rects == undefined || rects.length == 0) {
			return;
		}
		// For now we're going to grab the first rect of the element to use as the position for the vfx,
		// but this could be expanded in the future to support multiple rects or different shapes
		const rect = rects[0];

		if (!vfxPathAttributeData) {
			vfxTrigger(vfxComponentName(), rect, eventName);
		} else {
			const vfx = useVfx(vfxPathAttributeData);
			vfx(eventName, rect);
		}
	}

	// Note that the audio context is an accessor, and must be called before using
	const audioContext = useContext(AudioGroupContext);
	const triggerContext = useContext(TriggerActivationContext);

	const actionButton = createMemo(() => props.actionKey ?? "accept");
	const hotkeyIcon = createMemo(() => props.hotkeyAction ?? actionButton());
	const [root, setRoot] = createPropsRefSignal<HTMLDivElement>(() => props.ref);
	const [isPressed, setIsPressed] = createSignal(false);

	const isHidden = createMemo(() => IsControllerActive() && !!props.navTrayText && props.navTrayText.length > 0);
	const isDisabled = createMemo(() => props.disabled);

	const hotkeyIconProvider: HotkeyIconContextProvider = { disabled: isDisabled, actionName: hotkeyIcon };

	// Update the hotkey action with the registry if it changes, or the control is disabled
	const onMouseEnter: JSX.EventHandlerUnion<
		HTMLDivElement,
		MouseEvent,
		JSX.EventHandler<HTMLDivElement, MouseEvent>
	> = (event) => {
		triggerUiSFX("focus", "data-audio-focus");
		triggerUiVFX("focus");

		(props.onMouseEnter as JSX.EventHandler<HTMLDivElement, MouseEvent>)?.(event);
	};

	const onFocus = () => {
		if (props.isFeedbackEnabled) {
			Input.triggerForceFeedback(FEEDBACK_LOW, FEEDBACK_HIGH, FEEDBACK_DURATION);
		}
	};

	const onTouchComplete = (inputEvent: InputEngineEvent) => {
		if (inputEvent.detail.name == "touch-complete") {
			setIsPressed(false);
		}
	};

	onMount(() => {
		window.addEventListener(InputEngineEventName, onTouchComplete, true);
	});

	onCleanup(() => {
		window.removeEventListener(InputEngineEventName, onTouchComplete, true);
	});

	const onEngineInput = (inputEvent: InputEngineEvent) => {
		const isStart = inputEvent.detail.status == InputActionStatuses.START;
		const isFinish = inputEvent.detail.status == InputActionStatuses.FINISH;

		if (!isStart && !isFinish) {
			return;
		}

		if (inputEvent.detail.name == "touch-touch") {
			setIsPressed(true);
			if (props.disabled) {
				triggerUiSFX("pressError", "data-audio-error-press");
				triggerUiVFX("pressError");
			} else {
				triggerUiSFX("press", "data-audio-press");
				triggerUiVFX("press");
			}

			inputEvent.stopPropagation();
			inputEvent.preventDefault();
			return;
		}

		if (
			inputEvent.detail.name == "mousebutton-left" ||
			inputEvent.detail.name == actionButton() ||
			inputEvent.detail.name == "touch-tap" ||
			inputEvent.detail.name == "keyboard-enter"
		) {
			if (props.disabled) {
				if (isStart) {
					triggerUiSFX("pressError", "data-audio-error-press");
					triggerUiVFX("pressError");

					inputEvent.stopPropagation();
					inputEvent.preventDefault();
				}
			} else {
				if (isStart) {
					triggerUiSFX("press", "data-audio-press");
					triggerUiVFX("press");
				} else {
					activate();
				}

				inputEvent.stopPropagation();
				inputEvent.preventDefault();
			}
		} else {
			props["on:engine-input"]?.(inputEvent);
		}
	};

	function activate() {
		props.onActivate?.();

		triggerUiSFX("activate", "data-audio-activate");
		triggerUiVFX("activate");

		// If this activatable is inside a trigger, activate it (unless trigger is disabled)
		if (!props.disableTrigger) {
			triggerContext?.trigger(TriggerType.Activate, root());
		}
	}

	return (
		<div
			{...props}
			// ---- Directives ----
			ref={setRoot}
			use:isFocusable={[!props.disableFocus, props.autoFocus]}
			use:registerHotkey={[props.hotkeyAction, () => props.disabled != true, activate]}
			use:registerNavTray={[props.hotkeyAction, () => props.disabled != true, props.navTrayText]}
			// ---- DOM Attributes ----
			role={props.role ?? "button"}
			class={`pointer-events-auto ${props.class ?? ""}`}
			classList={{
				...props.classList,
				disabled: props.disabled,
				"cursor-not-allowed": props.disabled && !props.suppressPointerChanges,
				"cursor-pointer": !props.disabled && !props.suppressPointerChanges,
				pressed: isPressed(),
				hidden: isHidden(),
			}}
			tabIndex={props.disableFocus ? undefined : (props.tabIndex ?? -1)}
			// ---- Data ----
			data-audio-group-ref={props.audio?.group}
			data-audio-press-ref={props.audio?.onPress}
			data-audio-activate-ref={props.audio?.onActivate}
			data-audio-error-press-ref={props.audio?.onError}
			data-audio-focus-ref={props.audio?.onFocus}
			data-name={props.name ?? "Activatable"}
			data-activatable="true"
			// ---- Event Handlers ----
			on:focus={onFocus}
			onMouseEnter={onMouseEnter}
			on:engine-input={onEngineInput}
		>
			<HotkeyIconContext.Provider value={hotkeyIconProvider}>{props.children}</HotkeyIconContext.Provider>
		</div>
	);
};

/**
 * The base Activatable jsx component.
 * Used as the base for all components which require user interaction, like buttons and selectors.
 * Does not provide any style on its own.
 * ```tsx
 * // Example - Activatable Text
 * <Activatable onActivate={() => console.log("activated")}>I am activatable!</Activatable>
 * ```
 * Default implementation: {@link ActivatableComponent}
 * @param {ActivatableProps} props See {@link ActivatableProps} for a full list of properties
 *
 * Commonly Used Properties:
 * @param {boolean} props.disabled Is this control disabled both visually and for input? Default: false
 * @param {string} props.hotkeyAction The name of a hotkey action which activates this component. Default: undefined
 * @param {string} props.name The name of the component set as the data-name property - useful for debugging or searching the DOM tree. Default: "Activatable"
 * @param {() => void} props.onActivate Event which triggers when the control is activated either through hotkey, mouse click, touch, or other user interaction. Default: undefined
 */
export const Activatable = ComponentRegistry.register("Activatable", ActivatableComponent);
